<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount} from 'vue';
import {request} from '../api/client';
import {speak} from '../composables/useSpeech';
import {player} from '../composables/usePlayer';
const providers=ref<{id:string;name:string;ready:boolean}[]>([]),provider=ref('deepseek'),draft=ref(''),busy=ref(false),listening=ref(false),error=ref(''),auto=ref(true);
const messages=ref<{role:'user'|'assistant';content:string}[]>([]);
function stopVoice(){speechSynthesis.cancel()}
let recognition:any=null,disposed=false;
onMounted(async()=>{try{providers.value=await request('/speaking/providers')}catch{error.value='无法读取模型配置'}});
async function send(){if(busy.value||!draft.value.trim())return;const text=draft.value.trim();draft.value='';messages.value.push({role:'user',content:text});busy.value=true;error.value='';try{const result=await request<{text:string}>('/speaking/chat',{method:'POST',body:JSON.stringify({provider:provider.value,messages:messages.value.slice(-39)})});if(disposed)return;messages.value.push({role:'assistant',content:result.text});if(auto.value)speak(result.text,'en-US',1)}catch(e){if(!disposed){error.value=e instanceof Error?e.message:'发送失败';messages.value.pop();draft.value=text}}finally{busy.value=false}}
function record(){if(listening.value){recognition?.stop();return}const Constructor=(window as any).SpeechRecognition||(window as any).webkitSpeechRecognition;if(!Constructor){error.value='当前浏览器不支持语音输入，请使用支持语音识别的浏览器或文字输入。';return}player.pause();speechSynthesis.cancel();recognition=new Constructor();recognition.lang='en-US';recognition.interimResults=true;recognition.onresult=(e:any)=>{draft.value=Array.from(e.results as any[]).map((r:any)=>r[0].transcript).join(' ');if(e.results[e.results.length-1].isFinal){recognition.stop();void send()}};recognition.onend=()=>listening.value=false;recognition.onerror=()=>{listening.value=false;error.value='未能识别，请检查麦克风权限或重试。'};try{recognition.start();listening.value=true;error.value=''}catch{error.value='录音启动失败'}}
onBeforeUnmount(()=>{disposed=true;recognition?.abort();speechSynthesis.cancel()});
</script>
<template><div class="speaking"><span class="eyebrow">SPEAK · CONNECT · GROW</span><h1>你的英语口语老师</h1><p class="sub">聊生活、练表达。说完一句，老师接着聊。</p><section class="card"><div class="speak-controls"><label>对话模型 <select v-model="provider" :disabled="busy||listening"><option v-for="p in providers" :value="p.id">{{p.name}}{{p.ready?'':' · 待配置'}}</option></select></label><label><input type="checkbox" v-model="auto"> 自动朗读回答</label><button class="link" @click="stopVoice">停止朗读</button></div><p class="coach-note">默认英语口语老师。语音识别后的文字和最近对话将发送给所选模型；回答使用设备英语语音朗读。</p><div class="conversation" aria-live="polite"><p v-if="!messages.length" class="sub">Try saying: “I'd like to practise checking in at a hotel.”</p><article v-for="(m,i) in messages" :key="i" :class="m.role"><small>{{m.role==='user'?'你':'英语老师'}}</small><p>{{m.content}}</p><button v-if="m.role==='assistant'" class="link" @click="speak(m.content,'en-US',1)">♪ 再听一遍</button></article><p v-if="busy">老师正在思考…</p></div><p role="alert">{{error}}</p><textarea v-model="draft" :disabled="busy" rows="3" maxlength="6000" aria-label="你的表达" placeholder="说英语，或在这里输入…"></textarea><div class="speak-controls"><button class="primary" :disabled="busy" @click="record">{{listening?'■ 停止录音':'● 开始说话'}}</button><button class="bbc-secondary" :disabled="busy||listening||!draft.trim()" @click="send">发送</button><button class="link" :disabled="busy||listening" @click="messages=[];draft=''">新对话</button></div></section></div></template>
<style scoped>.speaking h1{margin:20px 0}.speaking .card{margin-top:28px;padding:24px}.speak-controls{display:flex;gap:16px;align-items:center;flex-wrap:wrap}.conversation{max-height:52vh;overflow:auto;margin:24px 0}.conversation article{padding:16px;border:1px solid var(--line);border-radius:16px;margin:12px 0;white-space:pre-wrap}.conversation .user{margin-left:12%;background:var(--bg)}.conversation .assistant{margin-right:8%}.conversation small{color:var(--accent)}.conversation p{line-height:1.8}.speaking textarea{width:100%;box-sizing:border-box;background:var(--bg);color:var(--text);border:1px solid var(--line);border-radius:12px;padding:14px;margin-bottom:16px;font:inherit}</style>

